return-response.set-body:
@{
            var reason = context.LastError?.Reason;
            var error = reason == "SubscriptionKeyNotFound"
                ? "subscription_key_required"
                : reason == "SubscriptionKeyInvalid"
                    ? "invalid_subscription_key"
                    : context.LastError?.PolicyId == "validate-user-token"
                        ? "invalid_user_token"
                        : "gateway_operation_failed";
            return new JObject(
                new JProperty("error", error),
                new JProperty("correlationId", context.RequestId.ToString())
            ).ToString();
        }
